      $('#date-value').text(`${year}年${month}月${day}日`);
      $('#time-value').text(time);
      $('#location-value').text(location);

      // --- 夏瑾变量 ---
      const xiajinAffection = _.get(all_variables, 'stat_data.夏瑾.好感度', [0])[0];
      $('#xiajin-affection-value').text(`${xiajinAffection} / 400`);
      const xiajinAffectionPercent = (xiajinAffection / 400) * 100;
      $('#xiajin-affection-bar').css('width', `${xiajinAffectionPercent}%`);

      // --- 秋芜变量 ---
      const qiuwuAffection = _.get(all_variables, 'stat_data.秋芜.好感度', [0])[0];
      $('#qiuwu-affection-value').text(`${qiuwuAffection} / 400`);
      const qiuwuAffectionPercent = (qiuwuAffection / 400) * 100;
      $('#qiuwu-affection-bar').css('width', `${qiuwuAffectionPercent}%`);

    }

    async function init() {
      await waitGlobalInitialized('Mvu');
      populateCharacterData();

      eventOn(Mvu.events.VARIABLE_UPDATE_ENDED, () => {
        populateCharacterData();
      });
    }

    $(errorCatched(init));
  </script>
